SELECT boh.*, u.user_name AS userName, b.name AS bookName FROM book_order_history boh LEFT JOIN book b ON b.id = boh.book_id LEFT JOIN user u ON u.id = boh.user_id
AND u.id = #{userId}
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND b.name LIKE CONCAT('%', #{bookName}, '%')
AND boh.is_return = #{isReturn}
AND boh.create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY boh.create_time DESC
LIMIT #{current}, #{size}

SELECT COUNT(*) FROM book_order_history boh LEFT JOIN book b ON b.id = boh.book_id LEFT JOIN user u ON u.id = boh.user_id
AND u.id = #{userId}
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND b.name LIKE CONCAT('%', #{bookName}, '%')
AND boh.is_return = #{isReturn}
AND boh.create_time BETWEEN #{startTime} AND #{endTime}
